#!/usr/bin/env node
/**
 * figma-import.mjs — turns figma-export.json (from tools/figma-exporter) into repo files.
 *
 *   node scripts/figma-import.mjs ~/Downloads/figma-export.json
 *   npm run figma:import -- ~/Downloads/figma-export.json
 *
 * Writes (all AUTO-GENERATED — never edit by hand, re-export instead):
 *   design/figma-export.json            raw export, minus PNGs (for diffs and for the agent)
 *   design/reference/*.png              Figma renders of T1–T5 (visual reference)
 *   src/styles/tokens.css               CSS variables (+ data-theme / data-surface modes), type classes, shadows
 *   src/styles/tailwind-tokens.ts       the same tokens as Tailwind theme values
 *   src/data/figma/layouts/<key>.json   t0, t0-hover-hi, t0-hover-bin, t0-5, t1: every element with position, size,
 *                                       rotation, props, texts, plus a CSS-ready box
 *   src/data/figma/motion/<key>.json    Figma-motion keyframes: animation-a, t0-hover-hi, t0-hover-bin
 *   src/data/figma/specs.json           structure of each component (layout, padding, colours, text styles)
 *   src/data/figma/assets.json          size / art box / collider / anchor of every SVG asset
 *   src/assets/figma/<group>/<key>.svg  theme-aware SVGs (bound colours → CSS variables)
 *   src/assets/figma/index.ts           typed registry of the SVGs as React components (via SVGR)
 * No dependencies. Node 18+.
 */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const input = process.argv[2] ? path.resolve(process.argv[2]) : path.join(ROOT, 'design/figma-export.json');
if (!fs.existsSync(input)) {
  console.error(`✗ Cannot find ${input}\n  Usage: node scripts/figma-import.mjs <path/to/figma-export.json>`);
  process.exit(1);
}
const data = JSON.parse(fs.readFileSync(input, 'utf8'));
if (!data.meta || !data.tokens) {
  console.error('✗ This does not look like a Pegboard Exporter file (missing meta/tokens).');
  process.exit(1);
}

const P = {
  raw: 'design/figma-export.json',
  refs: 'design/reference',
  tokensCss: 'src/styles/tokens.css',
  twTokens: 'src/styles/tailwind-tokens.ts',
  layouts: 'src/data/figma/layouts',
  motion: 'src/data/figma/motion',
  specs: 'src/data/figma/specs.json',
  assetsMeta: 'src/data/figma/assets.json',
  svgDir: 'src/assets/figma',
  svgIndex: 'src/assets/figma/index.ts',
  svgTypes: 'src/types/svg.d.ts',
  images: 'public/figma',
  imagesMeta: 'src/data/figma/images.json',
};
const abs = (p) => path.join(ROOT, p);
const write = (p, content) => {
  fs.mkdirSync(path.dirname(abs(p)), { recursive: true });
  fs.writeFileSync(abs(p), content);
};
const slug = (s) => String(s).toLowerCase().replace(/\+/g, ' plus').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const pascal = (s) => slug(s).split('-').filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join('').replace(/^(\d)/, '_$1');
const stamp = `AUTO-GENERATED by scripts/figma-import.mjs from Figma "${data.meta.page}" / "${data.meta.section || data.meta.home}" (exported ${data.meta.exportedAt}). Do not edit — change Figma, re-export, re-import.`;
const warnings = [];

// ---------------------------------------------------------------- pure black = --line-strong (Zeyi, 2026-10-28)
const BLACK = /^(black|#000|#000000)$/i;
const blackToToken = (paint) => (typeof paint === 'string' && BLACK.test(paint.split(' @')[0]) ? paint.replace(/^\S+/, 'var(--line-strong)') : paint);

// ---------------------------------------------------------------- MCP supplement (design/figma-mcp)
// Node data read from Figma with the MCP where this export has none (exporter < v2.1). The export always wins.
const SUP_DIR = 'design/figma-mcp';
const sup = fs.existsSync(abs(`${SUP_DIR}/supplement.json`)) ? JSON.parse(fs.readFileSync(abs(`${SUP_DIR}/supplement.json`), 'utf8')) : null;
const SIZING = { x: 'FIXED', h: 'HUG', f: 'FILL' };
const supArt = new Map((sup?.art || []).map((a) => [a.id, a]));
const supImages = new Map((sup?.images || []).map((i) => [i.id, i]));
let supApplied = 0;
function enrich(node) {
  if (!node || typeof node !== 'object') return;
  for (const k of ['fills', 'strokes']) if (Array.isArray(node[k])) node[k] = node[k].map(blackToToken);
  const code = sup?.nodes?.[node.id];
  if (code) {
    supApplied++;
    for (const t of code.split(' ')) {
      if (t === 'a') node.absolute ??= true;
      else if (t === 'L') { if (node.layout && node.layout.strokesInLayout === undefined) node.layout.strokesInLayout = true; }
      else if (/^f\d+$/.test(t)) node.font ??= sup.fonts[+t.slice(1)];
      else if (/^e\d+$/.test(t)) node.effectCss ??= sup.effects[+t.slice(1)];
      else if (/^[xhf]{2}$/.test(t)) node.sizing ??= [SIZING[t[0]], SIZING[t[1]]];
    }
  }
  const art = supArt.get(node.id);
  if (art && !node.asset) {
    node.asset = art.key;
    node.artBox = { x: art.box[0], y: art.box[1], w: art.box[2], h: art.box[3] };
    delete node.children;
  }
  const img = supImages.get(node.id);
  if (img && !node.image) node.image = img.key;
  const gap = sup?.counterGap?.[node.id];
  if (gap != null && node.layout && node.layout.counterGap == null) node.layout.counterGap = gap;
  const sides = sup?.strokeSides?.[node.id];
  if (sides && node.strokeWeight === 'mixed' && !node.strokeSides) node.strokeSides = sides;
  const kids = sup?.children?.[node.id];
  if (kids && !node.children) {
    node.children = structuredClone(kids);
    delete node.note;
  }
  (node.children || []).forEach(enrich);
}
for (const spec of Object.values(data.specs || {})) {
  (spec.variants || []).forEach((v) => enrich(v.tree));
  enrich(spec.tree);
}
for (const lay of Object.values(data.layouts || {})) (lay.items || []).forEach(enrich);

// Art SVGs downloaded with the MCP become theme-aware assets: the board's accent colour → var(--theme-accent).
const tokenValue = (css, mode) => {
  for (const col of data.tokens) {
    const v = col.variables.find((x) => x.css === css);
    if (!v) continue;
    const val = v.values[mode] ?? v.values[col.defaultMode];
    return val?.alias ? tokenValue(val.alias, mode) : val?.value;
  }
};
const themeModes = data.tokens.find((c) => c.modes.length > 1 && c.variables.some((v) => v.css === '--theme-accent'))?.modes.map((m) => m.slug) || [];
for (const a of sup?.art || []) {
  if (data.assets?.[a.key]) continue;
  const file = abs(`${SUP_DIR}/art/${a.key}.svg`);
  if (!fs.existsSync(file)) { warnings.push(`MCP art "${a.key}" is listed in supplement.json but ${SUP_DIR}/art/${a.key}.svg is missing`); continue; }
  let svg = fs.readFileSync(file, 'utf8');
  const theme = themeModes.find((m) => a.key.startsWith(`detail-board-${m}-`));
  const accent = theme && tokenValue('--theme-accent', theme);
  const [w, h] = ['width', 'height'].map((k) => +(svg.match(new RegExp(`<svg[^>]*\\s${k}="([\\d.]+)"`))?.[1] ?? 0));
  // Mirrored in Figma (relativeTransform scale -1): mirror the drawing inside its own box.
  if (a.flip === 'x') svg = svg.replace(/(<svg[^>]*>)([\s\S]*)(<\/svg>)/, `$1<g transform="matrix(-1 0 0 1 ${w} 0)">$2</g>$3`);
  data.assets = data.assets || {};
  data.assets[a.key] = { group: 'art', source: `${a.id} (MCP)`, w, h, art: null, collider: null, anchor: null, tokens: accent ? { [String(accent).toUpperCase()]: '--theme-accent' } : {}, svg };
}
for (const img of sup?.images || []) {
  const file = abs(`${SUP_DIR}/images/${img.key}.png`);
  if (data.images?.[img.key]) continue;
  if (!fs.existsSync(file)) { warnings.push(`MCP image "${img.key}" is missing in ${SUP_DIR}/images/`); continue; }
  data.images = data.images || {};
  data.images[img.key] = { source: `${img.id} (MCP)`, w: img.w, h: img.h, scale: 1, png: fs.readFileSync(file).toString('base64') };
}

// ---------------------------------------------------------------- tokens.css
function cssValue(v) {
  if (v == null) return 'initial';
  if (v.alias) return `var(${v.alias})`;
  if (typeof v.value === 'number') return v.unit ? `${v.value}${v.unit}` : String(v.value);
  return String(v.value);
}
const css = [`/* ${stamp} */`, ''];
const modeAttr = {}; // collection key -> data attribute
for (const col of data.tokens) {
  const multi = col.modes.length > 1;
  const attr = `data-${col.key}`;
  if (multi) modeAttr[col.key] = { attr, modes: col.modes.map((m) => m.slug), default: col.defaultMode };
  const block = (selector, mode) => {
    const lines = col.variables.map((v) => `  ${v.css}: ${cssValue(v.values[mode])};`);
    return `${selector} {\n${lines.join('\n')}\n}`;
  };
  css.push(`/* ${col.name}${multi ? ` — modes via [${attr}="…"]: ${col.modes.map((m) => m.slug).join(' | ')}` : ''} */`);
  if (!multi) css.push(block(':root', col.defaultMode));
  else {
    css.push(block(`:root,\n[${attr}="${col.defaultMode}"]`, col.defaultMode));
    for (const m of col.modes) if (m.slug !== col.defaultMode) css.push(block(`[${attr}="${m.slug}"]`, m.slug));
  }
  css.push('');
}
// fonts used by the text styles → expected CSS variables (set them with next/font in app/layout.tsx)
const families = [...new Set((data.textStyles || []).map((t) => t.fontFamily))];
const fontVar = (f) => `--font-${slug(f)}`;
const fallback = (f) => (/mono/i.test(f) ? 'ui-monospace, monospace' : /gentium|serif/i.test(f) ? 'Georgia, serif' : 'system-ui, sans-serif');
css.push('/* Effects (Figma effect styles) */', ':root {');
for (const e of data.effects || []) {
  css.push(`  ${e.css}: ${e.boxShadow || 'none'};`);
  css.push(`  ${e.css.replace('--shadow-', '--drop-shadow-')}: ${e.dropShadow || 'none'};`);
}
css.push('}', '');
css.push('/* Text styles (Figma "Pegboard/…") — font CSS variables must be provided by next/font in app/layout.tsx */');
for (const t of data.textStyles || []) {
  const lines = [
    `  font-family: var(${fontVar(t.fontFamily)}), "${t.fontFamily}", ${fallback(t.fontFamily)};`,
    `  font-size: ${t.fontSize}px;`,
    `  line-height: ${t.lineHeight};`,
    `  font-weight: ${t.fontWeight};`,
    `  letter-spacing: ${t.letterSpacing};`,
  ];
  if (t.italic) lines.push('  font-style: italic;');
  if (t.textCase === 'UPPER') lines.push('  text-transform: uppercase;');
  if (t.textCase === 'LOWER') lines.push('  text-transform: lowercase;');
  if (t.textDecoration === 'UNDERLINE') lines.push('  text-decoration: underline;');
  css.push(`.${t.className} {\n${lines.join('\n')}\n}`);
}
write(P.tokensCss, css.join('\n') + '\n');

// ---------------------------------------------------------------- tailwind-tokens.ts
const allVars = data.tokens.flatMap((c) => c.variables);
const colorVars = allVars.filter((v) => v.type === 'COLOR');
const tw = {
  colors: Object.fromEntries(colorVars.map((v) => [v.css.slice(2), `var(${v.css})`])),
  borderRadius: Object.fromEntries(allVars.filter((v) => /^radius\//.test(v.name)).map((v) => [v.name.split('/')[1], `var(${v.css})`])),
  boxShadow: Object.fromEntries((data.effects || []).map((e) => [e.css.replace('--shadow-', ''), `var(${e.css})`])),
  dropShadow: Object.fromEntries((data.effects || []).map((e) => [e.css.replace('--shadow-', ''), `var(${e.css.replace('--shadow-', '--drop-shadow-')})`])),
  fontFamily: Object.fromEntries(families.map((f) => [slug(f), [`var(${fontVar(f)})`, f, ...fallback(f).split(', ')]])),
};
write(P.twTokens, `// ${stamp}\n// Usage in tailwind.config.ts: import { figmaTokens } from './src/styles/tailwind-tokens'\n//   theme: { extend: { colors: figmaTokens.colors, borderRadius: figmaTokens.borderRadius, boxShadow: figmaTokens.boxShadow, fontFamily: figmaTokens.fontFamily } }\nexport const figmaTokens = ${JSON.stringify(tw, null, 2)} as const;\n\nexport const themeModes = ${JSON.stringify(modeAttr, null, 2)} as const;\n`);

// ---------------------------------------------------------------- layout (+ CSS-ready boxes)
function withCss(node, parentBox) {
  const n = { ...node };
  if (typeof n.cx === 'number') {
    const left = n.cx - n.w / 2;
    const top = n.cy - n.h / 2;
    n.css = {
      left: +(left - (parentBox ? parentBox.left : 0)).toFixed(2),
      top: +(top - (parentBox ? parentBox.top : 0)).toFixed(2),
      width: n.w,
      height: n.h,
      rotate: n.rotation ? +(-n.rotation).toFixed(2) : 0, // CSS degrees, clockwise (Figma is counter-clockwise)
    };
    if (n.children) n.children = n.children.map((c) => withCss(c, n.rotation ? null : { left, top }));
  }
  const bad = JSON.stringify([n.fills, n.strokes]).match(/\/\* ([^*]+) \*\//g);
  if (bad) warnings.push(`"${n.name}" uses colours from outside the Pegboard collections: ${bad.join(', ')}`);
  return n;
}
const layoutsIn = data.layouts || (data.layout ? { t1: data.layout } : {});
fs.rmSync(abs(P.layouts), { recursive: true, force: true });
const layoutCounts = {};
for (const [key, lay] of Object.entries(layoutsIn)) {
  if (lay.missing) { warnings.push(`layout "${key}": frame "${lay.missing}…" not found in Figma`); continue; }
  const out = {
    _note: stamp,
    _howTo: 'Coordinates are Figma px inside the 1440×1024 frame. css.left/top/width/height/rotate place the element (rotate = CSS degrees clockwise, transform-origin centre). Nested children have css relative to their parent. Array order = z-order (first = bottom).',
    frame: lay.frame,
    items: lay.items.map((i) => withCss(i, null)),
  };
  write(path.join(P.layouts, `${key}.json`), JSON.stringify(out, null, 2) + '\n');
  layoutCounts[key] = out.items.length;
}

// ---------------------------------------------------------------- motion (Figma keyframes)
fs.rmSync(abs(P.motion), { recursive: true, force: true });
const motionCounts = {};
for (const [key, m] of Object.entries(data.motion || {})) {
  if (m.missing) { warnings.push(`motion "${key}": frame "${m.missing}…" not found in Figma`); continue; }
  const out = {
    _note: stamp,
    _howTo: [
      'Each node lists Figma-motion tracks: t = seconds on the frame timeline, v = value, ease = easing INTO this keyframe (the first keyframe easing is ignored).',
      'Before the first keyframe a track holds its first value; after the last it holds the last value. The node box/center/opacity are the RESTING state (= the end state).',
      'TRANSLATION_X/Y add px to the resting position. ROTATION adds degrees COUNTER-clockwise (CSS rotate = -value). SCALE_XY multiplies. All pivot on the node centre.',
      'OPACITY replaces the opacity. Wrapper frames named "Hang · …", "Fly · …", "Motion · …" exist only to put the pivot where it must be (hook point, card centre): reproduce them as a positioned div of the same box with transform-origin: center.',
      'Motion (motion/react): keyframes = [v…], times = t / duration, ease per segment; or call the Figma MCP get_motion_context on the frame for ready motion.dev snippets.',
    ],
    ...m,
  };
  write(path.join(P.motion, `${key}.json`), JSON.stringify(out, null, 2) + '\n');
  motionCounts[key] = `${m.nodes.length} nodes · ${m.duration}s`;
}
write(P.specs, JSON.stringify({ _note: stamp, ...data.specs }, null, 2) + '\n');
// T2/T4/T5 differences from T1 (interaction states), read from Figma with the MCP until the exporter exports state frames.
if (sup?.states) write('src/data/figma/states.json', JSON.stringify({ _generated: stamp, ...sup.states }, null, 2) + '\n');

// ---------------------------------------------------------------- SVG assets
function themeSvg(key, svg, tokens) {
  const map = Object.fromEntries(Object.entries(tokens || {}).map(([hex, v]) => [hex.toUpperCase(), v]));
  // 1) unique ids per asset (several SVGs share Figma's clip ids otherwise)
  let out = svg.replace(/\bid="([^"]+)"/g, (_, id) => `id="${key}-${id}"`).replace(/url\(#([^)]+)\)/g, (_, id) => `url(#${key}-${id})`);
  // 2) sentinel colours → CSS variables, merged into one style attribute per element;
  //    pure black → var(--line-strong) (Zeyi), except inside <mask>/<clipPath> where black means "hidden".
  let inDefs = 0;
  out = out.replace(/<(\/?)([a-zA-Z]+)(\s[^<>]*?)?(\/?)>/g, (whole, closing, tag, attrs = '', selfClose) => {
    if (/^(mask|clipPath)$/.test(tag)) { if (closing) inDefs--; else if (!selfClose) inDefs++; return whole; }
    if (closing || !attrs) return whole;
    const styles = [];
    let a = attrs.replace(/\s(fill|stroke|stop-color|flood-color)="(#[0-9a-fA-F]{6}|#000|black)"/g, (m, prop, color) => {
      const v = BLACK.test(color) ? (inDefs ? null : '--line-strong') : map[color.toUpperCase()];
      if (!v) return m;
      styles.push(`${prop}:var(${v})`);
      return '';
    });
    if (!styles.length) return whole;
    if (/\sstyle="/.test(a)) a = a.replace(/\sstyle="([^"]*)"/, (m, s) => ` style="${s.replace(/;?\s*$/, ';')}${styles.join(';')}"`);
    else a += ` style="${styles.join(';')}"`;
    return `<${tag}${a}${selfClose}>`;
  });
  const left = out.match(/#FE[0-9A-F]{4}/gi);
  if (left) warnings.push(`${key}: unmapped sentinel colours ${[...new Set(left)].join(', ')}`);
  return out;
}
const meta = {};
const registry = [];
fs.rmSync(abs(P.svgDir), { recursive: true, force: true });
for (const [key, a] of Object.entries(data.assets || {})) {
  const rel = `${a.group}/${key}.svg`;
  write(path.join(P.svgDir, rel), themeSvg(key, a.svg, a.tokens));
  meta[key] = { group: a.group, file: rel, source: a.source, w: a.w, h: a.h, art: a.art, collider: a.collider, anchor: a.anchor, cssVars: [...new Set(Object.values(a.tokens || {}))] };
  registry.push({ key, rel, name: pascal(key) + 'Svg' });
}
write(P.assetsMeta, JSON.stringify({ _note: stamp, ...meta }, null, 2) + '\n');
const idx = [
  `// ${stamp}`,
  "// SVGs are imported as React components through SVGR (@svgr/webpack, see CLAUDE.md → 'SVG setup').",
  "import type { ComponentType, SVGProps } from 'react';",
  ...registry.map((r) => `import ${r.name} from './${r.rel}';`),
  '',
  'export type SvgComponent = ComponentType<SVGProps<SVGSVGElement>>;',
  'export const figmaSvg = {',
  ...registry.map((r) => `  '${r.key}': ${r.name},`),
  '} satisfies Record<string, SvgComponent>;',
  'export type FigmaSvgKey = keyof typeof figmaSvg;',
  '',
];
write(P.svgIndex, idx.join('\n'));
if (!fs.existsSync(abs(P.svgTypes))) {
  write(P.svgTypes, "declare module '*.svg' {\n  import type { ComponentType, SVGProps } from 'react';\n  const Svg: ComponentType<SVGProps<SVGSVGElement>>;\n  export default Svg;\n}\n");
}

// ---------------------------------------------------------------- image fills inside specs (served from public/figma)
const images = data.images || {};
if (Object.keys(images).some((k) => images[k].png)) {
  fs.rmSync(abs(P.images), { recursive: true, force: true });
  for (const [key, img] of Object.entries(images)) write(path.join(P.images, `${key}.png`), Buffer.from(img.png, 'base64'));
}
const imagesMeta = Object.fromEntries(Object.entries(images).map(([k, img]) => [k, { src: `/figma/${k}.png`, source: img.source, w: img.w, h: img.h, scale: img.scale }]));
write(P.imagesMeta, JSON.stringify({ _note: stamp, ...imagesMeta }, null, 2) + '\n');

// ---------------------------------------------------------------- reference PNGs + raw copy
const refs = data.references || {};
for (const [key, r] of Object.entries(refs)) {
  if (r.png) write(path.join(P.refs, `${key}.png`), Buffer.from(r.png, 'base64'));
}
const slim = {
  ...data,
  images: Object.fromEntries(Object.entries(images).map(([k, img]) => [k, { source: img.source, w: img.w, h: img.h, file: `${P.images}/${k}.png` }])),
  references: Object.fromEntries(Object.entries(refs).map(([k, r]) => [k, { name: r.name, w: r.w, h: r.h, file: `${P.refs}/${k}.png` }])),
};
const hasBinary = Object.keys(refs).some((k) => refs[k].png) || Object.keys(images).some((k) => images[k].png);
if (path.resolve(input) !== abs(P.raw) || hasBinary) write(P.raw, JSON.stringify(slim, null, 2) + '\n');

// ---------------------------------------------------------------- report
const pkg = fs.existsSync(abs('package.json')) ? JSON.parse(fs.readFileSync(abs('package.json'), 'utf8')) : {};
const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
if (!deps['@svgr/webpack']) warnings.push('@svgr/webpack is not installed yet — see CLAUDE.md → "SVG setup" before importing from src/assets/figma.');
console.log(`✓ Imported Figma export from ${data.meta.exportedAt}`);
console.log(`  tokens:   ${data.tokens.map((c) => `${c.key}(${c.variables.length}${c.modes.length > 1 ? ' × ' + c.modes.length + ' modes' : ''})`).join(', ')} → ${P.tokensCss}`);
console.log(`  type:     ${(data.textStyles || []).length} text styles, fonts needed: ${families.map((f) => `${f} → ${fontVar(f)}`).join(', ')}`);
console.log(`  layouts:  ${Object.entries(layoutCounts).map(([k, n]) => `${k}(${n})`).join(', ')} → ${P.layouts}/`);
console.log(`  motion:   ${Object.entries(motionCounts).map(([k, n]) => `${k}: ${n}`).join(', ') || 'none'} → ${P.motion}/`);
console.log(`  specs:    ${Object.keys(data.specs || {}).length} components → ${P.specs}`);
console.log(`  svg:      ${registry.length} assets → ${P.svgDir}/`);
console.log(`  images:   ${Object.keys(images).length} image fills → ${P.images}/`);
console.log(`  refs:     ${Object.keys(refs).length} reference PNGs → ${P.refs}/`);
if (warnings.length) {
  console.log(`\n⚠ ${warnings.length} warning(s):`);
  for (const w of warnings) console.log('  - ' + w);
}
